252	  //TODO: cache_invalid can't multi SM
253	  assign cache_invalid    = {wg_done,{(`NUMBER_CU-1){1'b0}}};
254	  //assign cache_invalid    = {/*host_rsp_valid_o*/wg_done,1'b0} ;
255	  assign host_rsp_valid_o = l2cache_finish_issue && is_flushing;
256	
257	  always@(posedge clk or negedge rst_n) begin
258	    if(!rst_n) begin
259	      is_flushing <= 'd0;
260	    end
261	    else if(wg_done) begin
262	      is_flushing <= 1'b1;
263	    end
264	    else if(l2cache_finish_issue) begin
265	      is_flushing <= 1'b0;
266	    end
267	    else begin
268	      is_flushing <= is_flushing;
269	    end
270	  end
